import{_ as e,o as t,c as d,a2 as r}from"./chunks/framework.D0_YsCyK.js";const h=JSON.parse('{"title":"审查域 D 报告：转发/隧道/流量计费","description":"","frontmatter":{},"headers":[],"relativePath":"audit/D-forward.md","filePath":"audit/D-forward.md","lastUpdated":1792447441000}'),a={name:"audit/D-forward.md"};function l(i,o,n,c,s,u){return t(),d("div",null,[...o[0]||(o[0]=[r('<h1 id="审查域-d-报告-转发-隧道-流量计费" tabindex="-1">审查域 D 报告：转发/隧道/流量计费 <a class="header-anchor" href="#审查域-d-报告-转发-隧道-流量计费" aria-label="Permalink to &quot;审查域 D 报告：转发/隧道/流量计费&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><ul><li><strong>审查范围</strong>：对比移植前基线 <code>5e1edce8</code>，检查 7 批 flyx 移植是否破坏既有转发/隧道/计费功能</li><li><strong>发现问题数</strong>：P0 0 个 / P1 0 个 / P2 1 个 / P3 2 个</li><li><strong>实际执行的测试</strong>： <ul><li><code>git diff 5e1edce8 HEAD</code> 逐文件对比（control_plane.go、handler.go、kernel_probe.go、kernel_relay.go、jobs.go、nftables 相关、mutations.go、flow/quota 文件）</li><li>路由重复性检查：187 个 <code>mux.HandleFunc</code> 注册，<code>sort | uniq -d</code> 无重复</li><li><code>go test ./internal/kernel/ -run &quot;TestSub|TestShare|TestClash&quot;</code> ✅ 通过</li><li><code>go test ./internal/kernel/ -run &quot;TestSubScript|TestChain|TestApplySub&quot;</code> ✅ 通过</li><li><code>go test ./internal/http/handler/ -run &quot;TestQuota|TestFlow|TestSubOver|TestUserQuota&quot;</code> ✅ 通过（10.1s）</li><li><code>go vet ./internal/kernel/</code> ✅ 通过</li><li>自编写实测：<code>TestScriptBeforeMarkChainOrder</code> 验证脚本改名后链式分组是否保留 ✅ 通过（脚本将&quot;香港 1&quot;改名为&quot;HK 1&quot;，<code>markChain</code> 仍通过 <code>Original</code> 正确设置 <code>ChainRole=landing</code>）</li></ul></li></ul><h2 id="p0-阻断" tabindex="-1">P0 阻断 <a class="header-anchor" href="#p0-阻断" aria-label="Permalink to &quot;P0 阻断&quot;">​</a></h2><p>无。</p><h2 id="p1-严重" tabindex="-1">P1 严重 <a class="header-anchor" href="#p1-严重" aria-label="Permalink to &quot;P1 严重&quot;">​</a></h2><p>无。</p><h2 id="p2-一般" tabindex="-1">P2 一般 <a class="header-anchor" href="#p2-一般" aria-label="Permalink to &quot;P2 一般&quot;">​</a></h2><h3 id="d-001-空订阅状态码变更-200-空-→-503" tabindex="-1">D-001 空订阅状态码变更（200+空 → 503） <a class="header-anchor" href="#d-001-空订阅状态码变更-200-空-→-503" aria-label="Permalink to &quot;D-001 空订阅状态码变更（200+空 → 503）&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/kernel_relay.go:609-612</code></li><li><strong>现象</strong>：<code>openSubscription</code> 在 <code>endpoints</code> 为空时，现在返回 <code>503 Service Unavailable</code> + 中文错误「订阅暂无可用节点（入站未启用或中转转发未建立）」，而移植前（<code>5e1edce8</code>）返回 <code>200</code> + 空 body。</li><li><strong>复现步骤</strong>： <ol><li>创建订阅，关联一个 <code>RelayOnly=1</code> 且中转转发未建立的入站</li><li><code>GET /api/v1/open_api/sub/&lt;token&gt;?format=clash</code></li><li>移植前：HTTP 200，空 body；现在：HTTP 503 + 错误文本</li></ol></li><li><strong>期望</strong>：行为变更应有明确记录。返回 503 更合理（避免客户端静默失败），但属于既有 API 的行为变更。</li><li><strong>实际</strong>：静默改为空 503。部分老旧客户端可能只处理 200，需要确认兼容性。</li><li><strong>影响范围</strong>：所有订阅客户端（Clash/sing-box/Loon/QX/Shadowrocket/Surge）在订阅无可用节点时的错误处理路径。</li><li><strong>修复方向</strong>：保留 503（更合理），但需在发版说明中明确标注此行为变更。如需最大兼容，可改为仍返回 200 但在 body 中嵌入错误注释（YAML <code>#</code> 注释）。</li></ul><h2 id="p3-体验-备注" tabindex="-1">P3 体验/备注 <a class="header-anchor" href="#p3-体验-备注" aria-label="Permalink to &quot;P3 体验/备注&quot;">​</a></h2><h3 id="d-002-非分享订阅-subscription-userinfo-头-total-恒为-0-已在-1-0-3-修复" tabindex="-1">D-002 非分享订阅 <code>Subscription-Userinfo</code> 头 <code>total</code> 恒为 0（已在 1.0.3 修复） <a class="header-anchor" href="#d-002-非分享订阅-subscription-userinfo-头-total-恒为-0-已在-1-0-3-修复" aria-label="Permalink to &quot;D-002 非分享订阅 `Subscription-Userinfo` 头 `total` 恒为 0（已在 1.0.3 修复）&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/kernel_relay.go:623-626</code>（修复前）</li><li><strong>现象</strong>：非分享订阅（<code>isShare(sub)==false</code>）的 <code>Subscription-Userinfo</code> 响应头中 <code>total=0</code>，导致 Clash 客户端不显示流量信息，只显示「远程」。</li><li><strong>根因</strong>：<code>total</code> 变量仅在 <code>isShare</code> 分支赋值，else 分支只累加 <code>up</code>/<code>down</code>，<code>total</code> 保持初始值 0。</li><li><strong>状态</strong>：已在本次审查前由主会话修复（<code>total = sub.TrafficLimit</code>），1.0.3 包含此修复。本报告记录备查。</li><li><strong>证据</strong>：用户实测截图显示「FLVX - 我的订阅」在修复前显示「远程」，修复后应显示流量。</li></ul><h3 id="d-003-externalprobe-points-字段新增-兼容性确认" tabindex="-1">D-003 <code>externalProbe.Points</code> 字段新增（兼容性确认） <a class="header-anchor" href="#d-003-externalprobe-points-字段新增-兼容性确认" aria-label="Permalink to &quot;D-003 `externalProbe.Points` 字段新增（兼容性确认）&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/kernel_probe.go:34-35</code></li><li><strong>变更</strong>：<code>externalProbe</code> 结构体新增 <code>Points []latencyPoint \\</code>json:&quot;points,omitempty&quot;`` 字段。</li><li><strong>影响分析</strong>： <ul><li>JSON 序列化：<code>omitempty</code> 保证无数据时不输出，旧客户端解析不受影响 ✅</li><li>Agent 侧（go-gost）：<code>grep -rn &quot;externalProbe&quot; go-gost/</code> 无命中，agent 不直接使用此结构体 ✅</li><li>既有 <code>inboundProbe</code> 行为：字段仅追加，无既有字段改名/删除/改类型 ✅</li></ul></li><li><strong>结论</strong>：无回归风险，记录备查。</li></ul><h2 id="确认无问题的项-d1-回归检查" tabindex="-1">确认无问题的项（D1 回归检查） <a class="header-anchor" href="#确认无问题的项-d1-回归检查" aria-label="Permalink to &quot;确认无问题的项（D1 回归检查）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>结果</th><th>证据</th></tr></thead><tbody><tr><td><code>control_plane.go</code> 变更</td><td>零变更</td><td><code>git diff 5e1edce8 HEAD -- &quot;**/control_plane.go&quot;</code> 为空</td></tr><tr><td><code>handler.go</code> 既有路由</td><td>仅增量，无修改/删除</td><td>diff 显示仅新增 7 个移植路由 + 2 个结构体字段 + 2 处配置钩子</td></tr><tr><td>路由重复注册</td><td>无</td><td>187 个 <code>mux.HandleFunc</code>，<code>sort | uniq -d</code> 为空</td></tr><tr><td>nftables 逻辑</td><td>零变更</td><td><code>git diff</code> 按 <code>*nft*</code> 文件名过滤为空</td></tr><tr><td>转发/隧道 CRUD (<code>mutations.go</code>, <code>kernel.go</code>)</td><td>零变更</td><td>diff 为空</td></tr><tr><td>流量/配额 (<code>flow_*.go</code>, <code>user_quota.go</code>, <code>subscription.go</code> 计费部分)</td><td>零变更</td><td>diff 为空</td></tr><tr><td><code>jobs.go</code></td><td>仅增 <code>h.jobsCtx = ctx</code> 一行</td><td>diff 确认</td></tr><tr><td>订阅流水线顺序（脚本 vs markChain）</td><td>安全</td><td>实测：脚本改名后 <code>markChain</code> 仍通过 <code>Original</code> 正确匹配（<code>chainMatchers</code> 同时匹配 <code>Name</code> 和 <code>Original</code>，见 <code>sub_chain.go:47-54</code>）</td></tr><tr><td><code>uniqueNames(..., rules)</code></td><td>正确</td><td><code>rules=true</code> 时预留规则组名避免冲突（<code>share.go:832-838</code>）</td></tr></tbody></table><h2 id="d2-计费正确性-代码审查-测试" tabindex="-1">D2 计费正确性（代码审查 + 测试） <a class="header-anchor" href="#d2-计费正确性-代码审查-测试" aria-label="Permalink to &quot;D2 计费正确性（代码审查 + 测试）&quot;">​</a></h2><ul><li><strong>流量统计加减</strong>：<code>flow_upload_batch.go</code>、<code>nftables_traffic.go</code> 零变更；相关测试通过。</li><li><strong>配额耗尽暂停/恢复</strong>：<code>user_quota.go</code>（<code>enforceUserQuotaIfNeeded</code>、<code>applyUserQuotaRelease</code>）零变更；测试通过。</li><li><strong>单向/双向计费</strong>：无相关代码变更。</li><li><strong>限速生效</strong>：<code>flow_policy*.go</code> 零变更。</li><li><strong>订阅流量头</strong>：见 D-002（已修复）。</li></ul><h2 id="d3-转发-隧道-crud-代码审查" tabindex="-1">D3 转发/隧道 CRUD（代码审查） <a class="header-anchor" href="#d3-转发-隧道-crud-代码审查" aria-label="Permalink to &quot;D3 转发/隧道 CRUD（代码审查）&quot;">​</a></h2><ul><li><strong>端口冲突检测</strong>：<code>kernel.go:849 inboundPortConflict</code>、<code>mutations.go:1545 validateTunnelEntryPortConflictsForNewEntriesTx</code> 零变更。</li><li><strong>离线节点操作</strong>：无相关代码变更。</li><li><strong>批量操作回滚</strong>：无相关代码变更。</li></ul><h2 id="未能验证的项" tabindex="-1">未能验证的项 <a class="header-anchor" href="#未能验证的项" aria-label="Permalink to &quot;未能验证的项&quot;">​</a></h2><ul><li><strong>nftables 实际生效</strong>：本机为 Linux VM 但无真实节点环境，<code>nft</code> 命令存在但无法模拟完整转发链路。代码零变更，风险低。需在真实节点验证（如有）。</li><li><strong>隧道转发端到端</strong>：需真实节点 + 隧道服务，未验证。代码零变更。</li><li><strong>大订阅性能（1000+ 节点）</strong>：未做压力测试。<code>ApplySubOptions</code> 为 O(n) 线性逻辑，<code>ApplySubScript</code> 有 1 秒超时保护，理论风险低。</li><li><strong>PostgreSQL 迁移</strong>：本机仅 SQLite。<code>latency_targets</code> 列的迁移修复（<code>repository.go</code> 显式 <code>AddColumn</code>）使用了 GORM Migrator API，PG 兼容性理论上无问题，但未实测。</li></ul>',23)])])}const b=e(a,[["render",l]]);export{h as __pageData,b as default};
